const L = params.length;
const bedW = L * 0.42;
const bedLen = L * 0.56;
const plankT = L * 0.035;
const bedY = L * 0.41;
const bedZ = -L * 0.16;
const wheelR = L * 0.18;
const wheelX = bedW * 0.57;
const wheelY = wheelR;
const wheelZ = -L * 0.2;
const darkWood = api.mix(params.woodColor, '#2b180d', 0.32);
const lightWood = api.mix(params.woodColor, '#d5a665', 0.2);
const wood = { preset: 'wood', color: params.woodColor, roughness: 0.82 };
const woodDark = { preset: 'wood', color: darkWood, roughness: 0.88 };
const woodLight = { preset: 'wood', color: lightWood, roughness: 0.78 };
const iron = { preset: 'metal', color: '#343638', metalness: 0.8, roughness: 0.38 };
const ironDark = { preset: 'metal', color: '#202224', metalness: 0.72, roughness: 0.48 };
const plankCount = 7;
const plankW = bedW / plankCount * 0.91;
for (let i = 0; i < plankCount; i++) {
  const x = -bedW / 2 + (i + 0.5) * bedW / plankCount;
  const p = api.box(plankW, plankT, bedLen).translate(x, bedY, bedZ);
  p.vertexColor((vx, vy, vz) => api.mix(params.woodColor, lightWood, 0.18 + 0.12 * api.noise2(vz * 13 / L, vx * 8 / L)));
  api.add(p, { preset: 'wood', roughness: 0.82 });
}
const crossZ = [-L * 0.405, -L * 0.15, L * 0.105];
for (let i = 0; i < crossZ.length; i++) api.add(api.box(bedW * 1.04, L * 0.045, L * 0.055).translate(0, bedY - plankT, crossZ[i]), woodDark);
const railH = L * 0.18;
const postT = L * 0.035;
for (let side = -1; side <= 1; side += 2) {
  const x = side * bedW * 0.49;
  for (let j = 0; j < 4; j++) {
    const z = bedZ - bedLen * 0.45 + j * bedLen * 0.3;
    api.add(api.box(postT, railH, postT).translate(x, bedY + railH * 0.48, z), woodDark);
  }
  api.add(api.box(postT, postT, bedLen * 0.94).translate(x, bedY + railH * 0.92, bedZ), wood);
  api.add(api.box(postT * 0.75, postT * 0.75, bedLen * 0.94).translate(x, bedY + railH * 0.48, bedZ), woodLight);
}
const backZ = bedZ - bedLen * 0.5;
for (let j = 0; j < 4; j++) {
  const x = -bedW * 0.45 + j * bedW * 0.3;
  api.add(api.box(postT, railH, postT).translate(x, bedY + railH * 0.48, backZ), woodDark);
}
api.add(api.box(bedW, postT, postT).translate(0, bedY + railH * 0.92, backZ), wood);
api.add(api.cylinder(L * 0.025, L * 0.025, bedW * 1.28, 12).rotate(0, 0, 90).translate(0, wheelY, wheelZ), ironDark);
for (let side = -1; side <= 1; side += 2) {
  const x = side * wheelX;
  api.add(api.torus(wheelR, L * 0.018).rotate(0, 90, 0).translate(x, wheelY, wheelZ), iron);
  api.add(api.torus(wheelR * 0.84, L * 0.022).rotate(0, 90, 0).translate(x, wheelY, wheelZ), woodDark);
  api.add(api.cylinder(L * 0.048, L * 0.048, L * 0.09, 12).rotate(0, 0, 90).translate(x, wheelY, wheelZ), ironDark);
  for (let s = 0; s < 10; s++) {
    const a = s * 36;
    const ar = a * Math.PI / 180;
    const sy = wheelY + Math.cos(ar) * wheelR * 0.43;
    const sz = wheelZ + Math.sin(ar) * wheelR * 0.43;
    api.add(api.cylinder(L * 0.009, L * 0.012, wheelR * 0.76, 6).rotate(a, 0, 0).translate(x, sy, sz), woodLight);
  }
  api.add(api.cylinder(L * 0.028, L * 0.038, L * 0.115, 10).rotate(0, 0, 90).translate(side * (wheelX + L * 0.045), wheelY, wheelZ), iron);
}
const frontZ = bedZ + bedLen * 0.48;
for (let side = -1; side <= 1; side += 2) {
  const x = side * bedW * 0.4;
  const path = [[x, bedY - L * 0.035, frontZ - L * 0.04], [x, bedY - L * 0.055, L * 0.31], [side * bedW * 0.34, bedY - L * 0.13, L * 0.5]];
  api.add(api.tube(path, L * 0.025, 8), woodDark);
  api.add(api.cylinder(L * 0.032, L * 0.032, L * 0.15, 10).rotate(90, 0, 0).translate(side * bedW * 0.34, bedY - L * 0.13, L * 0.545), wood);
  api.add(api.torus(L * 0.035, L * 0.009).rotate(90, 0, 0).translate(side * bedW * 0.34, bedY - L * 0.13, L * 0.62), iron);
}
api.add(api.box(bedW * 0.68, L * 0.055, L * 0.12).translate(0, bedY - L * 0.09, frontZ - L * 0.02), woodDark);
api.collider({ kind: 'box', halfExtents: [bedW * 0.52, L * 0.12, bedLen * 0.5], offset: [0, bedY + L * 0.07, bedZ] });
api.collider({ kind: 'box', halfExtents: [bedW * 0.62, wheelR, L * 0.045], offset: [0, wheelY, wheelZ] });
api.collider({ kind: 'box', halfExtents: [bedW * 0.44, L * 0.04, L * 0.3], offset: [0, bedY - L * 0.08, L * 0.31] });
return api.build();

doric-temple-detailed.source:
const PI = Math.PI;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const W = clamp(params.width, 12, 60);
const Ln = clamp(params.length, 24, 120);
const H = clamp(params.height, 7, 40);
const wr = clamp(params.weathering, 0, 1);
const marbleCol = params.marbleColor;
const roofCol = params.roofColor;
const bannerCol = params.bannerColor;
const goldCol = params.goldColor;

const MARBLE = { finish: 'marble', color: '#ffffff', roughness: 0.5 };
const FIGM = { finish: 'marble', color: '#ffffff', roughness: 0.32 };
const LIME = { finish: 'limestone', color: '#ffffff', roughness: 0.8 };
const GOLD = { finish: 'brass', color: goldCol, metalness: 0.9, roughness: 0.3 };
const FGOLD = { finish: 'brass', color: api.mix(goldCol, '#e8dcc0', 0.4), metalness: 0.45, roughness: 0.5 };
const ROOF = { finish: 'roof-tile', color: roofCol, roughness: 0.7 };
const ATTIC = { finish: 'plaster', color: '#8d8272', roughness: 0.95 };
const DARK = { finish: 'black-metal', color: '#07070a', roughness: 0.95 };
const BANNER = { finish: 'fabric', color: bannerCol, roughness: 0.85, doubleSided: true };

const nSteps = 4;
const sh = H * 0.09;
const stepH = sh / nSteps;
const run = clamp(H * 0.04, 0.3, 1.1);
let m = W * 0.04;
let xa = W / 2 - m, za = Ln / 2 - m;
let dx = 2 * xa / 7, dz = 2 * za / 16;
let cr = Math.min(dx, dz) * 0.19;
if (m < cr * 0.78 * 1.62 + 0.2) {
  m = cr * 0.78 * 1.62 + 0.2;
  xa = W / 2 - m; za = Ln / 2 - m;
  dx = 2 * xa / 7; dz = 2 * za / 16;
  cr = Math.min(dx, dz) * 0.19;
}
const rt = cr * 0.78;
const ab = rt * 1.62;
const t = ab * 0.98;
const ah = H * 0.055, fh = H * 0.075, cornH = H * 0.04, proj = H * 0.034;
const entH = ah + 0.09 + fh + cornH;
const hw = xa + t + proj;
const zf = za + t + proj;
const Wp = 2 * hw;
const ph = clamp(Wp * 0.125, H * 0.1, H * 0.24);
const acr = ph * 0.34;
const ch = Math.max(H - sh - entH - ph - acr, H * 0.28);
const yCol0 = sh;
const yArch0 = sh + ch;
const yTaen0 = yArch0 + ah;
const yGut0 = yTaen0 + 0.04;
const yFr0 = yGut0 + 0.05;
const yCor0 = yFr0 + fh;
const yCornTop = yCor0 + cornH;
const tw = fh * 0.62;

const trigTint = api.mix(marbleCol, '#b9ad98', 0.15);
const metTint = api.mix(marbleCol, '#c9bca3', 0.14);
const tympTint = api.mix(marbleCol, '#b8a98c', 0.3);
const figTint = api.mix(marbleCol, '#ffffff', 0.5);
const mutTint = api.mix(marbleCol, '#bfb299', 0.2);
const limeTint = api.mix(marbleCol, '#dccfae', 0.3);

function marbleAt(base, x, y, z) {
  const n = api.fbm2((x + z) * 0.9, y * 0.18 + 4.0, 3);
  let c = api.mix(base, n > 0 ? '#fffaf0' : '#cdbf9f', Math.min(1, Math.abs(n) * 1.3) * 0.38);
  const v = Math.abs(api.noise3(x * 0.7 + 5.0, y * 0.3, z * 0.7 - 2.0));
  if (v < 0.06) c = api.mix(c, '#7f8388', (1 - v / 0.06) * (0.25 + 0.55 * wr));
  const lowT = clamp(1 - y / (H * 0.3), 0, 1);
  const st = lowT * lowT * (0.2 + 0.7 * wr) * (0.65 + 0.35 * api.noise2(x * 0.5, z * 0.5 + y));
  if (st > 0.01) c = api.mix(c, '#d9c47a', clamp(st, 0, 0.75));
  return c;
}
function addM(mesh, tint) {
  mesh.vertexColor((x, y, z) => marbleAt(tint, x, y, z));
  api.add(mesh, MARBLE);
}
function addF(mesh, hex, mat) {
  mesh.vertexColor(() => hex);
  api.add(mesh, mat || MARBLE);
}
function addL(mesh, tint) {
  mesh.vertexColor((x, y, z) => marbleAt(tint, x, y, z));
  api.add(mesh, LIME);
}

// crepidoma
for (let i = 0; i < nSteps; i++) {
  const o = (nSteps - 1 - i) * run;
  const sw = W + 2 * o, sl = Ln + 2 * o;
  const yTop = (i + 1) * stepH;
  addM(api.roundedBox(sw, stepH, sl, Math.min(0.05, stepH * 0.3), 1).translate(0, i * stepH + stepH / 2, 0), marbleCol);
  api.collider({ kind: 'box', halfExtents: [sw / 2, stepH / 2, sl / 2], offset: [0, i * stepH + stepH / 2, 0] });
  let patches = null;
  for (let c = 0; c < 7; c++) {
    const si = Math.floor(api.rng() * 4);
    const horiz = si % 2 === 0;
    const R = horiz ? sl / 2 : sw / 2;
    const half = horiz ? sw / 2 : sl / 2;
    const u = (api.rng() * 2 - 1) * (half - 0.6);
    const w = 0.2 + api.rng() * 0.45, d = 0.1 + api.rng() * 0.2;
    let p;
    if (c < 4) p = api.box(w, 0.012, d).translate(u, yTop + 0.004, R - d / 2 - 0.02);
    else p = api.box(w, stepH * 0.3, 0.02).translate(u, yTop - stepH * 0.35, R + 0.004);
    p.rotate(0, si * 90, 0);
    if (patches) patches.merge(p); else patches = p;
  }
  addF(patches, api.mix(marbleCol, '#8d8473', 0.45));
}
for (let r = 0; r < 5; r++) {
  const rock = api.icosphereRock(0.1 + api.rng() * 0.08, 0.5).scale(1, 0.55, 1.2);
  const side = api.rng() < 0.5 ? 1 : -1;
  const o0 = (nSteps - 1) * run;
  rock.translate((api.rng() * 2 - 1) * (W / 2), stepH + 0.03, side * (Ln / 2 + o0 - 0.15 - api.rng() * 0.2));
  addF(rock, api.mix(marbleCol, '#b8ad96', 0.3));
}

// columns
const chipIdx = [];
while (chipIdx.length < 4) {
  const k = Math.floor(api.rng() * 46);
  if (chipIdx.indexOf(k) < 0) chipIdx.push(k);
}
let colCounter = 0;
function makeColumn(cx, cz) {
  const chipped = chipIdx.indexOf(colCounter) >= 0;
  colCounter++;
  const shaftH = ch * 0.87;
  const rad = tt => cr * (1 - 0.22 * tt) + cr * 0.045 * Math.sin(PI * tt) * (1 - 0.3 * tt);
  const ts = chipped
    ? [0, 0.12, 0.195, 0.2, 0.205, 0.3, 0.395, 0.4, 0.405, 0.52, 0.64, 0.76, 0.88, 1]
    : [0, 0.16, 0.4, 0.66, 0.86, 1];
  const prof = ts.map(tt => {
    const seam = chipped && (Math.abs(tt - 0.2) < 0.0001 || Math.abs(tt - 0.4) < 0.0001);
    return [rad(tt) * (seam ? 0.985 : 1), tt * shaftH];
  });
  const fd = cr * 0.085;
  const chipA = api.rng() * 6.28;
  const chipY = 0.2 * shaftH;
  const shaft = api.lathe(prof, 24).displace((x, y, z) => {
    const a = Math.atan2(z, x);
    let d = -fd * (0.5 - 0.5 * Math.cos(12 * a));
    if (chipped) {
      let da = a - chipA;
      da = Math.atan2(Math.sin(da), Math.cos(da));
      const dy = (y - chipY) / 0.3;
      d -= 0.07 * Math.exp(-(dy * dy + (da / 0.5) * (da / 0.5)));
    }
    return d;
  });
  const capH = ch * 0.13;
  const capP = [[rt, 0], [rt * 0.93, capH * 0.07], [rt * 1.03, capH * 0.1], [rt * 1.34, capH * 0.3], [rt * 1.58, capH * 0.52], [rt * 1.6, capH * 0.6]];
  shaft.merge(api.lathe(capP, 16).translate(0, shaftH, 0));
  shaft.merge(api.box(2 * ab, capH * 0.4, 2 * ab).translate(0, shaftH + capH * 0.8, 0));
  const tint = api.mix(marbleCol, api.rng() < 0.5 ? '#f6eedb' : '#d8cbb0', api.rng() * 0.3);
  addM(shaft.translate(cx, yCol0, cz), tint);
  if (chipped) {
    const rock = api.icosphereRock(0.15, 0.5).scale(1, 0.6, 1.2)
      .translate(cx + Math.cos(chipA) * (cr + 0.3), yCol0 + 0.08, cz + Math.sin(chipA) * (cr + 0.3));
    addF(rock, api.mix(marbleCol, '#b8ad96', 0.25));
  }
  api.collider({ kind: 'cylinder', radius: cr, halfHeight: ch / 2, offset: [cx, yCol0 + ch / 2, cz] });
}
for (let i = 0; i < 8; i++) {
  makeColumn(-xa + i * dx, za);
  makeColumn(-xa + i * dx, -za);
}
for (let j = 1; j < 16; j++) {
  makeColumn(xa, -za + j * dz);
  makeColumn(-xa, -za + j * dz);
}

// entablature
const sides = [
  { yaw: 0, R: za, half: xa, corner: true },
  { yaw: 90, R: xa, half: za, corner: false },
  { yaw: 180, R: za, half: xa, corner: true },
  { yaw: 270, R: xa, half: za, corner: false }
];
function beam(sd, y0, h, tin, tout) {
  const len = sd.corner ? 2 * (sd.half + tout) : 2 * (sd.half - tin);
  return api.box(len, h, tin + tout).translate(0, y0 + h / 2, sd.R + (tout - tin) / 2).rotate(0, sd.yaw, 0);
}
function ringMesh(y0, h, tin, tout) {
  const mm = beam(sides[0], y0, h, tin, tout);
  for (let i = 1; i < 4; i++) mm.merge(beam(sides[i], y0, h, tin, tout));
  return mm;
}
addM(api.box(2 * (xa - t + 0.1), ah, 2 * (za - t + 0.1)).translate(0, yArch0 + ah / 2, 0), api.mix(marbleCol, '#8a7f6c', 0.35));
addM(ringMesh(yArch0, ah, t, t), marbleCol);
addM(ringMesh(yTaen0, 0.04, t, t + 0.05), marbleCol);
addM(ringMesh(yGut0, fh + 0.05, t - 0.07, t - 0.07), metTint);
addM(ringMesh(yCor0 + 0.06, cornH - 0.06, t - 0.07, t + proj), marbleCol);

const groups = { body: null, groove: null, gutta: null, mut: null, disc: null };
const gkeys = ['body', 'groove', 'gutta', 'mut', 'disc'];
function gput(k, mesh) { if (groups[k]) groups[k].merge(mesh); else groups[k] = mesh; }
sides.forEach(sd => {
  const sg = { body: null, groove: null, gutta: null, mut: null, disc: null };
  const sput = (k, mesh) => { if (sg[k]) sg[k].merge(mesh); else sg[k] = mesh; };
  const trigU = [], metU = [];
  let metW;
  if (sd.corner) {
    const cF = xa + t - tw / 2;
    const sF = 2 * cF / 14;
    for (let k = 0; k < 15; k++) trigU.push(-cF + k * sF);
    for (let k = 0; k < 14; k++) metU.push(-cF + (k + 0.5) * sF);
    metW = sF - tw;
  } else {
    const sS = (2 * (za - t) + tw) / 32;
    metW = sS - tw;
    for (let i = 0; i < 31; i++) trigU.push(-za + t + metW + tw / 2 + i * sS);
    for (let j = 0; j < 32; j++) metU.push(-za + t + metW / 2 + j * sS);
  }
  const bodyH = fh - 0.05;
  trigU.forEach(u => {
    sput('body', api.box(tw, bodyH, 2 * t).translate(u, yFr0 + 0.05 + bodyH / 2, sd.R));
    sput('body', api.box(tw * 1.1, 0.05, 2 * t + 0.04).translate(u, yFr0 + 0.025, sd.R));
    [-1, 1].forEach(s => {
      sput('groove', api.box(tw * 0.1, bodyH * 0.8, 0.03).translate(u + s * tw * 0.17, yFr0 + 0.05 + bodyH / 2, sd.R + t));
    });
    for (let g = 0; g < 6; g++) {
      sput('gutta', api.cone(tw * 0.055, 0.05, 4).rotate(180, 0, 0).translate(u + (g - 2.5) * tw * 0.16, yGut0 + 0.025, sd.R + t));
    }
    sput('mut', api.box(tw * 0.96, 0.06, proj - 0.06).translate(u, yCor0 + 0.03, sd.R + t + proj * 0.5 - 0.03));
  });
  const rd = Math.min(metW, fh) * 0.3;
  metU.forEach(u => {
    sput('mut', api.box(metW * 0.9, 0.06, proj - 0.06).translate(u, yCor0 + 0.03, sd.R + t + proj * 0.5 - 0.03));
    sput('disc', api.cylinder(rd, rd, 0.03, 8).rotate(90, 0, 0).translate(u, yFr0 + fh / 2, sd.R + t - 0.07 + 0.012));
  });
  gkeys.forEach(k => { if (sg[k]) gput(k, sg[k].rotate(0, sd.yaw, 0)); });
});
addM(groups.body, trigTint);
addF(groups.groove, '#5f584a');
addF(groups.gutta, api.mix(marbleCol, '#ffffff', 0.2));
addF(groups.mut, mutTint);
addF(groups.disc, '#ffffff', FGOLD);

// roof
const slopeD = (ph - 0.5) / hw;
const aR = Math.atan(slopeD);
const yRidge = yCornTop + ph - 0.25;
const xEave = hw + 0.4;
const Ls = xEave / Math.cos(aR);
const roofLen = 2 * (zf - 0.55);
const amp = 0.09;
const nT = Math.max(8, Math.round(roofLen / 0.5));
const pitch = roofLen / nT;
const rpts = [[-roofLen / 2, -0.2], [roofLen / 2, -0.2], [roofLen / 2, 0]];
for (let k = nT - 1; k >= 0; k--) {
  for (let j = 3; j >= 0; j--) {
    rpts.push([-roofLen / 2 + (k + j / 4) * pitch, amp * 0.5 * (1 - Math.cos(2 * PI * j / 4))]);
  }
}
const slabBase = api.extrude(rpts, Ls).rotate(0, 90, 0).rotate(0, 0, -aR * 180 / PI);
const xm = xEave / 2;
const ym = yRidge - slopeD * xm - amp / 2;
const roofVC = (x, y, z) => api.mix('#ffffff', '#b09580', clamp(0.5 + 0.6 * api.noise2(z * 2.3 + 7.0, x * 0.3), 0, 1));
const slabR = slabBase.clone().translate(xm, ym, 0);
const slabL = slabBase.clone().rotate(0, 180, 0).translate(-xm, ym, 0);
slabR.vertexColor(roofVC); api.add(slabR, ROOF);
slabL.vertexColor(roofVC); api.add(slabL, ROOF);
const ridge = api.cylinder(0.2, 0.2, roofLen, 8).rotate(90, 0, 0).translate(0, yRidge + 0.04, 0);
ridge.vertexColor((x, y, z) => api.mix('#d9c9bd', '#8f6e5d', clamp(0.5 + 0.6 * api.noise2(z * 1.3, 2.0), 0, 1)));
api.add(ridge, ROOF);
const yb = x => yRidge - slopeD * Math.abs(x) - amp / 2 - 0.2 / Math.cos(aR) + 0.03;
const wA = xa + t - 0.1, hwc = hw - 0.06;
const yBaseCore = yArch0 + ah - 0.01;
const core = api.extrude([
  [-wA, yBaseCore], [wA, yBaseCore], [wA, yCor0 + 0.02], [hwc, yCor0 + 0.02],
  [hwc, yb(hwc)], [0, yb(0)], [-hwc, yb(hwc)], [-hwc, yCor0 + 0.02], [-wA, yCor0 + 0.02]
], 2 * (zf - 0.7));
api.add(core, ATTIC);

// pediments
function palmette(sc) {
  const p = api.sphere(0.13 * sc, 1);
  const angs = [-62, -42, -21, 0, 21, 42, 62];
  for (let i = 0; i < 7; i++) {
    const L = sc * (1.0 - 0.45 * Math.abs(angs[i]) / 62);
    p.merge(api.cone(0.12 * sc, L, 5).translate(0, L / 2, 0).scale(1, 1, 0.35).rotate(0, 0, angs[i]));
  }
  [-1, 1].forEach(s => p.merge(api.sphere(0.1 * sc, 0).scale(1, 1, 0.5).translate(s * 0.34 * sc, 0.12 * sc, 0)));
  return p;
}
function figStanding(h, raised) {
  const f = api.cone(0.2 * h, 0.62 * h, 8).translate(0, 0.31 * h, 0);
  f.merge(api.capsule(0.11 * h, 0.44 * h).translate(0, 0.64 * h, 0));
  f.merge(api.sphere(0.078 * h, 1).translate(0, 0.92 * h, 0));
  f.merge(api.cylinder(0.028 * h, 0.034 * h, 0.36 * h, 5).translate(0, -0.18 * h, 0).rotate(0, 0, raised ? -140 : -8).translate(-0.13 * h, 0.78 * h, 0));
  f.merge(api.cylinder(0.028 * h, 0.034 * h, 0.36 * h, 5).translate(0, -0.18 * h, 0).rotate(0, 0, 8).translate(0.13 * h, 0.78 * h, 0));
  return f;
}
function figSeated(h) {
  const f = api.capsule(0.1 * h, 0.45 * h).translate(0, 0.62 * h, 0);
  f.merge(api.sphere(0.08 * h, 1).translate(0, 0.93 * h, 0));
  f.merge(api.box(0.5 * h, 0.28 * h, 0.45 * h).translate(0, 0.14 * h, 0.02 * h));
  f.merge(api.capsule(0.09 * h, 0.5 * h).rotate(90, 0, 0).translate(0, 0.34 * h, 0.2 * h));
  f.merge(api.cylinder(0.06 * h, 0.07 * h, 0.34 * h, 5).translate(0, 0.17 * h, 0.42 * h));
  return f;
}
function figRecline(h, hd) {
  const f = api.capsule(0.1 * h, 0.62 * h).rotate(0, 0, 90).translate(-hd * 0.06 * h, 0.11 * h, 0);
  f.merge(api.capsule(0.09 * h, 0.34 * h).rotate(0, 0, -hd * 35).translate(hd * 0.2 * h, 0.24 * h, 0));
  f.merge(api.sphere(0.075 * h, 1).translate(hd * 0.31 * h, 0.4 * h, 0));
  return f;
}
const hwT = hw - 0.12;
const apexT = ph - 0.06;
const availAt = x => Math.max(0.25, apexT * (1 - Math.abs(x) / hwT) - 0.2);
const xsFrac = [0, 0.19, 0.38, 0.57, 0.76];
const apexSc = acr / 1.35;
const al = Math.atan2(ph, hw);

function buildEnd(yaw) {
  const tzFront = zf - 0.45;
  const tymp = api.extrude([[-hw + 0.12, 0], [hw - 0.12, 0], [0, ph - 0.06]], 0.3)
    .translate(0, yCornTop, tzFront - 0.15).rotate(0, yaw, 0);
  addM(tymp, tympTint);
  let rake = null;
  [-1, 1].forEach(s => {
    const Lr = Math.hypot(hw, ph) + 0.12;
    const rk = api.box(Lr, 0.28, 0.7).rotate(0, 0, s > 0 ? -al * 180 / PI : al * 180 / PI)
      .translate(s * (hw / 2 + Math.sin(al) * 0.14), yCornTop + ph / 2 + Math.cos(al) * 0.14, zf - 0.35);
    if (rake) rake.merge(rk); else rake = rk;
  });
  addM(rake.rotate(0, yaw, 0), marbleCol);
  let figs = null;
  for (let k = -4; k <= 4; k++) {
    const ak = Math.abs(k);
    const sg = k < 0 ? -1 : 1;
    const xi = sg * xsFrac[ak] * hwT;
    const av = availAt(xi);
    let fm, hh;
    if (ak === 0) { hh = Math.min(av * 0.98, ph * 0.9); fm = figStanding(hh, false); }
    else if (ak === 1) { hh = av * 0.85; fm = figStanding(hh, true); }
    else if (ak === 2) { hh = av * 0.82; fm = figStanding(hh, false); }
    else if (ak === 3) { hh = av * 0.88; fm = figSeated(hh); }
    else { hh = clamp(av / 0.36, 0.6, 2.0); fm = figRecline(hh, -sg); }
    if (ak === 2 || ak === 3) fm.rotate(0, -sg * 14, 0);
    fm.translate(xi, yCornTop + 0.1, tzFront + 0.1 * hh + 0.04);
    if (figs) figs.merge(fm); else figs = fm;
  }
  figs.rotate(0, yaw, 0);
  figs.vertexColor((x, y, z) => api.mix(figTint, '#fffdf7', clamp(0.5 + 0.5 * api.noise3(x * 3, y * 3, z * 3), 0, 1)));
  api.add(figs, FIGM);
  const placeAc = (x, y, sc) => {
    addM(api.roundedBox(0.8 * sc, 0.3 * sc, 0.4 * sc, 0.03, 1).translate(x, y + 0.15 * sc, zf - 0.35).rotate(0, yaw, 0), marbleCol);
    const pal = palmette(sc).translate(x, y + 0.3 * sc, zf - 0.35).rotate(0, yaw, 0);
    pal.vertexColor(() => '#ffffff');
    api.add(pal, GOLD);
  };
  placeAc(0, yCornTop + ph - 0.05, apexSc);
  const cs = apexSc * 0.72;
  placeAc(hw - 0.45 * cs - 0.2, yCornTop + 0.12, cs);
  placeAc(-(hw - 0.45 * cs - 0.2), yCornTop + 0.12, cs);
}
buildEnd(0);
buildEnd(180);

// cella and pronaos
const cxo = xa - dx * 0.95;
const wt = 0.75;
const zB = -(za - dz * 1.2);
const zFc = za - dz * 2.3;
const zp = zFc - dz * 2.0;
const wallLen = zFc - zB;
const wallZc = (zFc + zB) / 2;
[-1, 1].forEach(s => {
  const cxw = s * (cxo - wt / 2);
  addL(api.roundedBox(wt, ch, wallLen, 0.03, 1).translate(cxw, yCol0 + ch / 2, wallZc), limeTint);
  addL(api.roundedBox(wt + 0.14, 0.32, wallLen + 0.14, 0.04, 1).translate(cxw, yCol0 + 0.16, wallZc), limeTint);
  addL(api.roundedBox(wt + 0.18, 0.3, wallLen + 0.18, 0.04, 1).translate(cxw, yArch0 - 0.15, wallZc), limeTint);
  addM(api.roundedBox(wt + 0.3, ch, 0.4, 0.03, 1).translate(cxw, yCol0 + ch / 2, zFc - 0.1), marbleCol);
  addM(api.roundedBox(wt + 0.5, 0.36, 0.55, 0.04, 1).translate(cxw, yArch0 - 0.4, zFc - 0.1), marbleCol);
  api.collider({ kind: 'box', halfExtents: [wt / 2, ch / 2, wallLen / 2], offset: [cxw, yCol0 + ch / 2, wallZc] });
});
addL(api.roundedBox(2 * cxo, ch, wt, 0.03, 1).translate(0, yCol0 + ch / 2, zB + wt / 2), limeTint);
addL(api.roundedBox(2 * cxo + 0.14, 0.32, wt + 0.14, 0.04, 1).translate(0, yCol0 + 0.16, zB + wt / 2), limeTint);
addL(api.roundedBox(2 * cxo + 0.18, 0.3, wt + 0.18, 0.04, 1).translate(0, yArch0 - 0.15, zB + wt / 2), limeTint);
api.collider({ kind: 'box', halfExtents: [cxo, ch / 2, wt / 2], offset: [0, yCol0 + ch / 2, zB + wt / 2] });
const dw = Math.min(2.6, dx * 0.9);
const dh = ch * 0.62;
const pw = (cxo - wt) - dw / 2;
[-1, 1].forEach(s => {
