  api.collider({ kind: 'box', halfExtents: [pw / 2, ch / 2, wt / 2], offset: [s * (dw / 2 + pw / 2), yCol0 + ch / 2, zp - wt / 2] });
  addM(api.roundedBox(0.3, dh, wt + 0.1, 0.03, 1).translate(s * (dw / 2 + 0.15), yCol0 + dh / 2, zp - wt / 2 + 0.05), marbleCol);
});
addL(api.roundedBox(dw, ch - dh, wt, 0.03, 1).translate(0, yCol0 + dh + (ch - dh) / 2, zp - wt / 2), limeTint);
api.collider({ kind: 'box', halfExtents: [dw / 2, (ch - dh) / 2, wt / 2], offset: [0, yCol0 + dh + (ch - dh) / 2, zp - wt / 2] });
addM(api.roundedBox(dw + 0.7, 0.32, wt + 0.14, 0.04, 1).translate(0, yCol0 + dh + 0.16, zp - wt / 2 + 0.07), marbleCol);
addM(api.roundedBox(dw + 1.1, 0.2, wt + 0.34, 0.04, 1).translate(0, yCol0 + dh + 0.42, zp - wt / 2 + 0.12), marbleCol);
addM(api.roundedBox(dw + 0.6, 0.1, wt + 0.3, 0.03, 1).translate(0, yCol0 + 0.05, zp - wt / 2 + 0.1), marbleCol);
api.add(api.box(dw, dh, 0.1).translate(0, yCol0 + dh / 2, zp - wt + 0.3), DARK);
api.add(api.box(dw - 0.1, 0.05, wt).translate(0, yCol0 + 0.03, zp - wt / 2 - 0.1), DARK);

// banners
const bw = dx * 0.42;
const bl = ch * 0.52;
const bt = 0.08;
const yTopB = yArch0 - 0.03;
[1, 3, 5].forEach((k, bi) => {
  const xc = -xa + (k + 0.5) * dx;
