  const notchH = bw * 0.4;
  const b = api.plane(bw, bl, 6, 18).rotate(90, 0, 0).translate(0, -bl / 2 - bt, 0).warp((x, y, z) => {
    const v = clamp((-bt - y) / bl, 0, 1);
    const f = 1 - (notchH / bl) * (1 - Math.abs(x) / (bw / 2));
    const yy = -bt + (y + bt) * f;
    return [x, yy, z + 0.07 * v * Math.sin(yy * 2.4 + x * 3.0 + ph0)];
