  api.add(api.cylinder(0.23, 0.23, 0.036, 14).rotate(90, 0, 0).translate(xc, yE, za + 0.052), BANNER);
});

api.collider({ kind: 'box', halfExtents: [hw, (yCornTop + ph - yArch0) / 2, zf], offset: [0, (yArch0 + yCornTop + ph) / 2, 0] });

