const W = params.width, D = params.depth;
const F = Math.max(1, Math.round(params.floors));
const variant = Math.round(params.variant);
const FH = 3.1, Y0 = 0.5, H = F * FH;
const mats = {
 wall: { preset: 'concrete', finish: 'plaster', color: params.wallColor, roughness: 0.92 },
 base: { preset: 'stone', finish: 'stone', color: params.baseColor, roughness: 0.95 },
 trim: { preset: 'stone', finish: 'marble', color: params.trimColor, roughness: 0.7 },
 roof: { preset: 'brick', finish: 'roof-tile', color: params.roofColor, roughness: 0.85 },
 wood: { preset: 'wood', finish: 'oak', color: params.shutterColor, roughness: 0.75 },
 glass: { preset: 'glass', color: '#34495c', roughness: 0.1, metalness: 0.3, opacity: 0.8 },
 iron: { preset: 'metal', color: '#26262b', roughness: 0.5, metalness: 0.6 },
 lamp: { preset: 'emissive', color: '#ffcf7a', emissive: '#ffb347', emissiveIntensity: 2 }
};
const acc = {};
function put(key, mesh) { if (acc[key]) { acc[key].merge(mesh); } else { acc[key] = mesh; } }
function bx(key, w, h, d, x, y, z, ry, ox, oz) {
 put(key, api.box(w, h, d).translate(x, y, z).rotate(0, ry || 0, 0).translate(ox || 0, 0, oz || 0));
}
// body
put('base', api.roundedBox(W + 0.3, 0.5, D + 0.3, 0.05).translate(0, 0.25, 0));
put('wall', api.roundedBox(W, H, D, 0.04).translate(0, Y0 + H / 2, 0));
put('base', api.roundedBox(W + 0.12, 0.95, D + 0.12, 0.03).translate(0, Y0 + 0.475, 0));
// string courses
for (let f = 1; f < F; f++) {
 bx('trim', W + 0.14, 0.16, D + 0.14, 0, Y0 + f * FH - 0.35, 0);
}
// quoins
const kq = Math.floor(H / 0.55);
for (let k = 2; k < kq; k++) {
 const y = Y0 + 0.25 + k * 0.5;
 for (const sx of [1, -1]) {
 for (const sz of [1, -1]) {
 if (k % 2 === 0) {
 bx('trim', 0.55, 0.46, 0.34, sx * (W / 2 + 0.05 - 0.275), y, sz * (D / 2 + 0.05 - 0.17));
 } else {
 bx('trim', 0.34, 0.46, 0.55, sx * (W / 2 + 0.05 - 0.17), y, sz * (D / 2 + 0.05 - 0.275));
 }
 }
 }
}
// cornice with dentils
const topY = Y0 + H;
bx('trim', W + 0.5, 0.12, D + 0.5, 0, topY + 0.06, 0);
bx('trim', W + 0.3, 0.2, D + 0.3, 0, topY - 0.1, 0);
for (let x = -W / 2 + 0.2; x < W / 2 - 0.1; x += 0.3) {
 for (const s of [1, -1]) {
 bx('trim', 0.14, 0.1, 0.12, x, topY - 0.26, s * (D / 2 + 0.08));
 }
}
// windows
function windowAt(x, fy, tall, ry, ox, oz, f) {
 const h = tall ? 2.1 : 1.4;
 const w = tall ? 0.95 : 0.88;
 const cy = tall ? fy + 1.15 : fy + 1.7;
 bx('trim', w + 0.24, h + 0.24, 0.1, x, cy, 0.05, ry, ox, oz);
 bx('glass', w, h, 0.06, x, cy, 0.09, ry, ox, oz);
 bx('trim', 0.04, h, 0.08, x, cy, 0.1, ry, ox, oz);
 bx('trim', w, 0.04, 0.08, x, cy + h * 0.15, 0.1, ry, ox, oz);
 bx('trim', w + 0.55, 0.2, 0.2, x, cy + h / 2 + 0.22, 0.1, ry, ox, oz);
 if (!tall) {
 bx('trim', w + 0.4, 0.09, 0.3, x, cy - h / 2 - 0.16, 0.15, ry, ox, oz);
 }
 if (params.shutters) {
 for (const s of [-1, 1]) {
 const sx = x + s * (w / 2 + 0.34);
 bx('wood', 0.42, h + 0.1, 0.05, sx, cy, 0.03, ry, ox, oz);
 for (let k = 0; k < 3; k++) {
 bx('wood', 0.34, 0.035, 0.02, sx, cy - h / 2 + (k + 0.7) * h / 3.4, 0.07, ry, ox, oz);
 }
 }
 }
 if (tall && f > 0) {
 bx('trim', 2.0, 0.12, 0.75, x, fy - 0.06, 0.375, ry, ox, oz);
 for (let k = 0; k < 9; k++) {
 bx('iron', 0.03, 0.95, 0.03, x - 0.96 + k * 0.24, fy + 0.475, 0.72, ry, ox, oz);
 }
 bx('iron', 2.0, 0.04, 0.04, x, fy + 0.95, 0.72, ry, ox, oz);
 for (const s of [-1, 1]) {
 bx('iron', 0.04, 0.04, 0.7, x + s * 0.98, fy + 0.95, 0.37, ry, ox, oz);
 bx('iron', 0.03, 0.95, 0.03, x + s * 0.98, fy + 0.475, 0.37, ry, ox, oz);
 bx('trim', 0.2, 0.32, 0.5, x + s * 0.6, fy - 0.28, 0.25, ry, ox, oz);
 }
 }
}
function facade(len, ry, ox, oz, front) {
 const n = front ? 2 * Math.floor((len - 1.6) / 4) + 1 : Math.max(1, Math.floor((len - 1.2) / 2.6));
 for (let f = 0; f < F; f++) {
 const fy = Y0 + f * FH;
 for (let i = 0; i < n; i++) {
 const x = -len / 2 + (i + 0.5) * len / n;
 const center = front && (i === (n - 1) / 2);
 if (center && f === 0) { continue; }
 const tall = center && f > 0 && params.balcony;
 windowAt(x, fy, tall, ry, ox, oz, f);
 }
 }
}
facade(W, 0, 0, D / 2, true);
facade(W, 180, 0, -D / 2, false);
facade(D, 90, W / 2, 0, false);
facade(D, -90, -W / 2, 0, false);
// door on the front
const dz = D / 2;
bx('trim', 0.22, 2.35, 0.16, -0.68, Y0 + 1.175, 0.08, 0, 0, dz);
bx('trim', 0.22, 2.35, 0.16, 0.68, Y0 + 1.175, 0.08, 0, 0, dz);
bx('trim', 1.9, 0.22, 0.24, 0, Y0 + 2.46, 0.12, 0, 0, dz);
put('trim', api.extrude([[-1.0, 0], [1.0, 0], [0, 0.4]], 0.2).translate(0, Y0 + 2.57, 0.1 + dz));
bx('wood', 1.14, 2.2, 0.08, 0, Y0 + 1.1, 0.04, 0, 0, dz);
for (const px of [-0.28, 0.28]) {
 for (const py of [0.6, 1.55]) {
 bx('wood', 0.4, 0.7, 0.03, px, Y0 + py, 0.09, 0, 0, dz);
 }
}
put('iron', api.sphere(0.04, 1).translate(0.4, Y0 + 1.05, 0.14 + dz));
bx('base', 2.0, 0.25, 0.6, 0, 0.125, 0.62, 0, 0, dz);
bx('base', 1.7, 0.25, 0.5, 0, 0.375, 0.4, 0, 0, dz);
// wall lantern beside the door
bx('iron', 0.05, 0.05, 0.22, 1.15, Y0 + 2.1, 0.11, 0, 0, dz);
put('lamp', api.sphere(0.09, 1).translate(1.15, Y0 + 2.05, 0.24 + dz));
// roof
const eaveY = Y0 + H + 0.12;
let rhR = 0;
if (variant === 0) {
 const oh = 0.6, hd = D / 2 + oh, rh = hd * 0.42, len = W + 2 * oh;
 rhR = rh;
 const sl = Math.sqrt(hd * hd + rh * rh);
 const ang = Math.atan2(rh, hd) * 180 / Math.PI;
 for (const s of [1, -1]) {
 const p = api.box(len, 0.1, sl);
 const nc = Math.floor(sl / 0.32);
 for (let k = 0; k < nc; k++) {
 p.merge(api.box(len, 0.05, 0.1).translate(0, 0.07, -sl / 2 + 0.18 + k * 0.32));
 }
 p.rotate(s * ang, 0, 0).translate(0, eaveY + rh / 2 - 0.04, s * hd / 2);
 put('roof', p);
 bx('wood', len, 0.16, 0.06, 0, eaveY - 0.06, s * (hd - 0.02));
 }
 put('roof', api.cylinder(0.12, 0.12, len, 8).rotate(0, 0, 90).translate(0, eaveY + rh + 0.02, 0));
 put('wall', api.extrude([[-hd, 0], [hd, 0], [0, rh + 0.06]], W + 0.1).rotate(0, 90, 0).translate(0, Y0 + H, 0));
} else if (variant === 1) {
 const oh = 0.55, rh = Math.min(W, D) * 0.45;
 rhR = rh * 0.8;
 put('roof', api.cone(1, rh, 4).rotate(0, 45, 0).scale((W / 2 + oh) / 0.7071, 1, (D / 2 + oh) / 0.7071).translate(0, eaveY + rh / 2 - 0.03, 0));
 put('roof', api.sphere(0.22, 1).translate(0, eaveY + rh + 0.05, 0));
 for (const s of [1, -1]) {
 bx('wood', W + 2 * oh, 0.16, 0.06, 0, eaveY - 0.06, s * (D / 2 + oh));
 bx('wood', 0.06, 0.16, D + 2 * oh, s * (W / 2 + oh), eaveY - 0.06, 0);
 }
} else {
 for (const s of [1, -1]) {
 bx('wall', W + 0.2, 0.55, 0.25, 0, Y0 + H + 0.275 + 0.12, s * (D / 2 - 0.02));
 bx('wall', 0.25, 0.55, D + 0.2, s * (W / 2 - 0.02), Y0 + H + 0.275 + 0.12, 0);
 bx('trim', W + 0.38, 0.08, 0.4, 0, Y0 + H + 0.62 + 0.12, s * (D / 2 - 0.02));
 bx('trim', 0.4, 0.08, D + 0.38, s * (W / 2 - 0.02), Y0 + H + 0.62 + 0.12, 0);
 }
 bx('base', W, 0.1, D, 0, Y0 + H + 0.12, 0);
 bx('wall', 1.5, 1.1, 1.5, W * 0.25, Y0 + H + 0.67, -D * 0.2);
 bx('trim', 1.7, 0.1, 1.7, W * 0.25, Y0 + H + 1.27, -D * 0.2);
 bx('wood', 0.7, 0.95, 0.06, W * 0.25, Y0 + H + 0.6, -D * 0.2 + 0.77);
 const px = -W * 0.2, pz = D * 0.05;
 for (const sx of [-1, 1]) {
 for (const sz of [-1, 1]) {
 bx('wood', 0.1, 2.2, 0.1, px + sx * 1.3, Y0 + H + 1.22, pz + sz * 1.0);
 }
 }
 for (let k = 0; k < 7; k++) {
 bx('wood', 0.08, 0.1, 2.3, px - 1.35 + k * 0.45, Y0 + H + 2.35, pz);
 }
 bx('wood', 2.8, 0.1, 0.1, px, Y0 + H + 2.28, pz - 1.0);
 bx('wood', 2.8, 0.1, 0.1, px, Y0 + H + 2.28, pz + 1.0);
}
// chimney
if (variant !== 2 && params.chimney) {
 const cx = (variant === 0 ? 0.27 : 0.18) * W;
 const cz = variant === 0 ? -D * 0.12 : 0;
 const top = eaveY + rhR * 0.9 + 0.6;
 const base = Y0 + H;
 bx('wall', 0.7, top - base, 0.7, cx, (base + top) / 2, cz);
 bx('trim', 0.84, 0.12, 0.84, cx, top - 0.12, cz);
 bx('trim', 0.92, 0.1, 0.92, cx, top + 0.05, cz);
 put('roof', api.cylinder(0.1, 0.12, 0.35, 8).translate(cx - 0.17, top + 0.27, cz));
 put('roof', api.cylinder(0.1, 0.12, 0.35, 8).translate(cx + 0.17, top + 0.27, cz));
}
for (const key in acc) { api.add(acc[key], mats[key]); }
api.collider({ kind: 'box', halfExtents: [W / 2 + 0.15, (H + 0.5) / 2, D / 2 + 0.15], offset: [0, (H + 0.5) / 2, 0] });
return api.build();

