const lime1 = '#ddd5c0', lime2 = '#b7b2a3', lime3 = '#ece3cc', olive = '#6a7843', olive2 = '#86924f', dry = '#a89d70', sage = '#a9b698';
const top = params.height * 0.8;
const cl = function (t) { return t < 0 ? 0 : (t > 1 ? 1 : t); };
const mat = { preset: 'stone', color: '#ffffff', roughness: 0.95 };
for (const p of parts) {
  p.mesh.vertexColor(function (x, y, z) {
    const n = api.noise3(x * 0.05, y * 0.2, z * 0.05);
    const s = api.noise3(x * 0.3, y * 1.4, z * 0.3);
    const g = api.noise3(x * 0.035 + 9, y * 0.12, z * 0.035 - 4);
    let c = api.mix(lime1, lime2, cl(0.5 + n * 0.7));
    c = api.mix(c, lime3, cl(s * 0.5));
    if (y > top) {
      c = api.mix(olive, dry, cl(0.5 + g));
    } else if (g > 0.15) {
      c = api.mix(c, olive2, cl((g - 0.15) * 3));
    }
    if (y < 3) { c = api.mix(c, sage, 0.6); }
    return c;
  });
  api.add(p.mesh, mat);
}
api.autoColliders('trimesh');
return api.build();

