const parts = api.library('terrain', { size: params.size, height: params.height, resolution: params.resolution, roughness: params.roughness, variant: params.variant, color: '#cfc8b6' });
const limeA = '#ece5d3';
const limeB = '#b9b4a6';
const olive = '#6a7842';
const olive2 = '#4f6234';
for (const p of parts) {
  p.mesh.vertexColor((x, y, z) => {
    const n = api.fbm2(x * 0.08, z * 0.08, 3);
    const s = api.noise2(x * 0.45, y * 1.6);
    const m = api.noise2(x * 0.035 + 10, z * 0.035);
    let c;
    if (y < 3) {
      c = api.mix('#7f9468', '#b2ab8c', Math.min(1, Math.max(0, 0.5 + 0.5 * n)));
    } else {
      let t = 0.5 + 0.35 * s + 0.3 * n;
      t = Math.min(1, Math.max(0, t));
      c = api.mix(limeA, limeB, t);
      const g = 0.5 + 0.5 * m;
      let k = 0;
      if (y > 44) k = 0.45 + 0.5 * (g - 0.4);
      else if (g > 0.55) k = (g - 0.55) * 2.2;
      k = Math.min(0.9, Math.max(0, k));
      if (k > 0) c = api.mix(c, g > 0.7 ? olive2 : olive, k);
    }
    return c;
  });
  api.add(p.mesh, { preset: 'stone', color: '#ffffff', roughness: 0.95 });
}
api.autoColliders('trimesh');
return api.build();
